mapper.select:
SELECT p.payment_id, u.user_id, p.payment_method, SUM(p.total_price) AS total_price, p.status, p.created_at FROM PAYMENTS p LEFT JOIN USERS u ON p.uuid = u.uuid LEFT JOIN ROOM_RESERVATION rr ON p.resort_reserv_id = rr.resort_reserv_id LEFT JOIN ROOM R ON r.room_id = rr.room_id
r.resort_id = #{resortID}
AND u.user_id LIKE '%' || #{keyword} || '%'
AND p.created_at BETWEEN #{atStart} AND #{atEnd}
AND p.status != '결제취소' GROUP BY p.payment_id, u.user_id, p.payment_method, p.status, p.created_at
